/* ============================================================================
   ШРИФТ ДЛЯ PDF: PT Sans, только нужные буквы

   jsPDF из коробки знает лишь латиницу: русский текст в PDF превращался бы в
   пустоту. Проверено — в готовом файле слова «Ведомость» не оказывалось вовсе.
   Поэтому шрифт кладём свой.

   PT Sans, лицензия SIL Open Font License — встраивать и продавать можно.
   Полный шрифт весит 443 КБ на начертание. Здесь он урезан до того, что
   реально печатается: кириллица, латиница, цифры, знаки препинания и ₽.
   Вышло 29 КБ вместо 443 — папку, которую носят на флешке, раздувать незачем.

   Файл собран заново из исходного шрифта; править его руками бессмысленно.
   ========================================================================== */
(function (root) {
  'use strict';
  var ОБЫЧНЫЙ = '';
  var ЖИРНЫЙ = '';

  /* Ставим шрифт в документ. Зовётся один раз на каждый новый PDF: файлы
     живут внутри документа, а не в библиотеке. */
  function поставить(doc) {
    if (!doc || !doc.addFileToVFS) return false;
    doc.addFileToVFS('PTSans.ttf', ОБЫЧНЫЙ);
    doc.addFont('PTSans.ttf', 'PTSans', 'normal');
    doc.addFileToVFS('PTSans-Bold.ttf', ЖИРНЫЙ);
    doc.addFont('PTSans-Bold.ttf', 'PTSans', 'bold');
    doc.setFont('PTSans', 'normal');
    return true;
  }
  root.WMPdfFont = { install: поставить, name: 'PTSans' };
})(typeof self !== 'undefined' ? self : this);
